   if g.release_speed:self.speed=g.release_speed
   if g.release=='staged':
    super().move(hand=[g.grip or 1.5]*4+[0,g.rot],n=30,wait=10)
    super().move(hand=[.5]*4+[0,g.rot],n=40,wait=20)
   elif g.release=='fingers':
