import sys,argparse,json,numpy as np,casa_tool
sys.path.insert(0,'/app/output')
from gen_baseline import Controller,BASE,BASE_ROT
from scipy.spatial.transform import Rotation,Slerp
class Dual(Controller):
 def both(self,right=None,left=None):
  s=self.s;old=s.targets.copy();ends=[];paths=[];durations=[]
  for k,h,spec in [(0,12,right),(6,18,left)]:
   goal=old.copy();n=1;wait=0
   if spec:
    p,r,hand,n,wait=spec
    if p is not None:goal[k:k+3]=BASE_ROT.T@(np.asarray(p)-BASE)
    if r is not None:goal[k+3:k+6]=Rotation.from_matrix(BASE_ROT.T@r).as_rotvec()
    if hand is not None:goal[h:h+6]=hand
   ends.append(goal);durations.append((n,wait));paths.append(Slerp([0,1],Rotation.from_rotvec(np.stack([old[k+3:k+6],goal[k+3:k+6]]))))
  for t in range(max(sum(x) for x in durations)):
   a=old.copy()
   for j,(k,h) in enumerate([(0,12),(6,18)]):
    n,wait=durations[j];v=min(t/max(1,n-1),1.);a[k:k+6]=(1-v)*old[k:k+6]+v*ends[j][k:k+6];a[k+3:k+6]=paths[j](v).as_rotvec();a[h:h+6]=(1-v)*old[h:h+6]+v*ends[j][h:h+6]
   s.step(a)
  self.report()
 def run(self,g):
  top=np.diag([1.,-1.,-1.]);push=np.array([[0,0,1],[1,0,0],[0,1,0.]])
  grip=[1.5]*4+[1.2,1.5];lh=[1.5]*4+[1.2,1.4];op=[0]*6
  self.move(p=[2.90,-1.98,1.20],r=top,hand=[.6]*4+[.2,1.4],n=18,wait=4)
  self.move(p=[2.91,-1.98,1.06],n=13,wait=4)
  self.move(hand=grip,n=13,wait=7)
  self.move(p=self.position()+[0,0,.14],n=18,wait=4)
  rp=(self.position()+[-.045,.16,-.035],None,None,20,3)
  lp=([2.53,-1.99,1.22],push,lh,12,2)
  if g.prep=='carry':self.both(right=rp,left=lp)
  else:self.both(right=rp)
  self.both(right=(self.position()+[0,.19,0],None,None,24,4))
  if g.prep=='release':self.both(right=(None,None,op,20,1),left=lp)
  else:self.both(right=(None,None,op,20,1))
  rp=(self.position()+[0,-.20,0],None,None,15,3)
  if g.prep=='away':self.both(right=rp,left=lp)
  elif g.overlap:self.both(right=rp,left=([2.60,-1.89,1.15],None,None,9,2))
  else:self.both(right=rp)
  rp=([2.99,-1.98,1.27],None,None,12,3)
  if g.overlap:
   self.both(right=rp,left=([2.72,-1.89,1.15],None,None,10,3))
  else:
   self.both(right=rp,left=([2.60,-1.89,1.15],None,None,9,2))
   self.move(arm='left',p=[2.72,-1.89,1.15],n=10,wait=3)
  self.move(arm='left',p=[2.80,-1.80,1.15],n=14,wait=3)
  self.move(arm='left',p=[2.86,-1.70,1.15],n=14,wait=4)
  self.move(arm='left',p=[2.60,-2.03,1.22],n=15,wait=10)
p=argparse.ArgumentParser();p.add_argument('--prep',default='carry');p.add_argument('--overlap',action='store_true');p.add_argument('--out',required=True);p.add_argument('--render',action='store_true');g=p.parse_args()
s=casa_tool.Session('/app/instance.npz');c=Dual(s,1.);c.run(g);s.save_trajectory(path=g.out)
bid=s.model.body('obj_main').id;q=s.data.xquat[bid][[1,2,3,0]];print('FINAL',json.dumps(dict(**s.check(),sha=s.state_sha(),milk=s.data.xpos[bid].tolist(),tilt=float(np.arccos(np.clip(Rotation.from_quat(q).as_matrix()[2,2],-1,1))),opening=s.env.microwave.get_door_state(s.env)['door'],config=vars(g))),flush=True)
if g.render:
 from PIL import Image
 Image.fromarray(s.render_grid((640,480))).save(g.out[:-4]+'.png')
s.close()
