class Variant(Controller):
 def __init__(self,s,g):super().__init__(s,1.);self.g=g;self.stage=0
 def move(self,*args,**kw):
  self.stage+=1;g=self.g
  if self.stage in g.stages:
   self.curve=g.curve
   kw['n']=max(2,round(kw['n']*g.factor))
   kw['wait']=max(1,kw['wait']+g.wait_add)
  else:self.curve='linear'
  if self.stage==7:
   if g.relax:
    sid=self.s.model.site('gripper0_right_grip_site').id
    super().move(p=self.position(),r=self.s.data.site_xmat[sid].reshape(3,3).copy(),n=10,wait=10)
   if g.preopen:
    super().move(hand=[.8]*4+[.6,1.5],n=10,wait=5)
  super().move(*args,**kw)
 def run(self):super().run()
p=argparse.ArgumentParser();p.add_argument('--stages',type=lambda s:[int(x) for x in s.split(',')],default=[]);p.add_argument('--curve',default='linear');p.add_argument('--factor',type=float,default=1.);p.add_argument('--wait_add',type=int,default=0);p.add_argument('--relax',action='store_true');p.add_argument('--preopen',action='store_true');p.add_argument('--out',required=True);p.add_argument('--render',action='store_true');g=p.parse_args()
s=casa_tool.Session('/app/instance.npz');c=Variant(s,g);c.run();s.save_trajectory(path=g.out)
bid=s.model.body('obj_main').id;q=s.data.xquat[bid][[1,2,3,0]];print('FINAL',json.dumps(dict(**s.check(),sha=s.state_sha(),milk=s.data.xpos[bid].tolist(),tilt=float(np.arccos(np.clip(Rotation.from_quat(q).as_matrix()[2,2],-1,1))),opening=s.env.microwave.get_door_state(s.env)['door'],config=vars(g))),flush=True)
if g.render:
 from PIL import Image
 Image.fromarray(s.render_grid((640,480))).save(g.out[:-4]+'.png')
s.close()
